begin;
with j as (select * from jsonb_to_recordset($law7d0024$[{"code_id":"GK_RF","article_number":"317","version_date":"1994-11-30","article_text":"1. Денежные обязательства должны быть выражены в рублях (статья 140).\n\n2. В денежном обязательстве может быть предусмотрено, что оно подлежит оплате в рублях в сумме, эквивалентной определенной сумме в иностранной валюте или в условных денежных единицах (экю, \"специальных правах заимствования\" и др.). В этом случае подлежащая уплате в рублях сумма определяется по официальному курсу соответствующей валюты или условных денежных единиц на день платежа, если иной курс или иная дата его определения не установлены законом или соглашением сторон.\n\n3. Использование иностранной валюты, а также платежных документов в иностранной валюте при осуществлении расчетов на территории Российской Федерации по обязательствам допускается в случаях, в порядке и на условиях, определенных законом или в установленном им порядке.","article_title":"Статья 317. Валюта денежных обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"524d0321ebaba840842da5293ee9206bda53cce209dba71dbdec7b16ff36e72d"},{"code_id":"GK_RF","article_number":"317.1","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 317.1. Проценты по денежному обязательству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64fabe95d849588f806cfc714ea30e5d29cf7de23abe3a20e6c305cde4c395fa"},{"code_id":"GK_RF","article_number":"318","version_date":"1994-11-30","article_text":"Если иное не предусмотрено законом, сумма, выплачиваемая по денежному обязательству непосредственно на содержание гражданина, в том числе в возмещение вреда, причиненного жизни или здоровью, либо по договору пожизненного содержания, увеличивается пропорционально повышению установленной в соответствии с законом величины прожиточного минимума.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 318. Увеличение сумм, выплачиваемых на содержание гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"087607f1ecd296f012d2ff89081b5f882ea15f52a4b25dca8c820c7e6f473271"},{"code_id":"GK_RF","article_number":"319","version_date":"1994-11-30","article_text":"Сумма произведенного платежа, недостаточная для исполнения денежного обязательства полностью, при отсутствии иного соглашения погашает прежде всего издержки кредитора по получению исполнения, затем - проценты, а в оставшейся части - основную сумму долга.","article_title":"Статья 319. Очередность погашения требований по денежному обязательству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"726ddb9da2dd52e13329c990e86f16dffe9025ca88ae7b6ae2ea0e4f309c9c0e"},{"code_id":"GK_RF","article_number":"319.1","version_date":"1994-11-30","article_text":"1. В случае, если исполненного должником недостаточно для погашения всех однородных обязательств должника перед кредитором, исполненное засчитывается в счет обязательства, указанного должником при исполнении или без промедления после исполнения.\n\n2. Если иное не предусмотрено законом или соглашением сторон, в случаях, когда должник не указал, в счет какого из однородных обязательств осуществлено исполнение, и среди таких обязательств имеются те, по которым кредитор имеет обеспечение, исполнение засчитывается в пользу обязательств, по которым кредитор не имеет обеспечения.\n\n3. Если иное не предусмотрено законом или соглашением сторон, в случаях, когда должник не указал, в счет какого из однородных обязательств осуществлено исполнение, преимущество имеет то обязательство, срок исполнения которого наступил или наступит раньше, либо, когда обязательство не имеет срока исполнения, то обязательство, которое возникло раньше. Если сроки исполнения обязательств наступили одновременно, исполненное засчитывается пропорционально в погашение всех однородных требований.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 319.1. Погашение требований по однородным обязательствам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c0e158255fddf8028c014ec059fb8e545795ab6c2116b918a18377178449f06"},{"code_id":"GK_RF","article_number":"32","version_date":"1994-11-30","article_text":"1. Опека устанавливается над малолетними, а также над гражданами, признанными судом недееспособными вследствие психического расстройства.\n\n2. Опекуны являются представителями подопечных в силу закона и совершают от их имени и в их интересах все необходимые сделки.","article_title":"Статья 32. Опека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca1b53c97512b6b3aa586973834c91245b7cfdb70f86da9d8b8e36b1e00d8330"},{"code_id":"GK_RF","article_number":"320","version_date":"1994-11-30","article_text":"1. Если должник по альтернативному обязательству (статья 3081), имеющий право выбора, не сделал выбор в пределах установленного для этого срока, в том числе путем исполнения обязательства, кредитор по своему выбору вправе потребовать от должника совершения соответствующего действия или воздержаться от совершения действия.\n\n2. Если право выбора по альтернативному обязательству (статья 3081) предоставлено кредитору или третьему лицу и такой кредитор или третье лицо не сделали выбор в пределах установленного для этого срока, должник исполняет обязательство по своему выбору.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 320. Исполнение альтернативного обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13e63b4cca8b24ef2fb851c4aa76358a5e68569af4ec305620d7e77c5714f264"},{"code_id":"GK_RF","article_number":"320.1","version_date":"1994-11-30","article_text":"1. Если должник по факультативному обязательству (статья 3082) к установленному сроку не приступил к основному исполнению, кредитор вправе потребовать основного исполнения обязательства.\n\n2. К обязательству, предусматривающему совершение должником одного из двух или нескольких действий, применяются правила об исполнении альтернативного обязательства (статья 320), если оно не может быть признано факультативным обязательством.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 320.1. Исполнение факультативного обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b031056310120e7a85ac1c09779d21070fe2f36c1516f5eaa9e5aec4538c58b"},{"code_id":"GK_RF","article_number":"321","version_date":"1994-11-30","article_text":"Если в обязательстве участвуют несколько кредиторов или несколько должников, то каждый из кредиторов имеет право требовать исполнения, а каждый из должников обязан исполнить обязательство в равной доле с другими постольку, поскольку из закона, иных правовых актов или условий обязательства не вытекает иное.","article_title":"Статья 321. Исполнение обязательства, в котором участвуют несколько кредиторов или несколько должников","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b9dbc0afe76777d75a9db6edd65526971861484a7211dc4e8509060676bf1b7"},{"code_id":"GK_RF","article_number":"322","version_date":"1994-11-30","article_text":"1. Солидарная обязанность (ответственность) или солидарное требование возникает, если солидарность обязанности или требования предусмотрена договором или установлена законом, в частности при неделимости предмета обязательства.\n\n2. Обязанности нескольких должников по обязательству, связанному с предпринимательской деятельностью, равно как и требования нескольких кредиторов в таком обязательстве, являются солидарными, если законом, иными правовыми актами или условиями обязательства не предусмотрено иное.","article_title":"Статья 322. Солидарные обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"336acb6a6da69d32db6d3b59da9b12f7b4db076c2e0948658fd1d1db04423986"},{"code_id":"GK_RF","article_number":"323","version_date":"1994-11-30","article_text":"1. При солидарной обязанности должников кредитор вправе требовать исполнения как от всех должников совместно, так и от любого из них в отдельности, притом как полностью, так и в части долга.\n\n2. Кредитор, не получивший полного удовлетворения от одного из солидарных должников, имеет право требовать недополученное от остальных солидарных должников.\n\nСолидарные должники остаются обязанными до тех пор, пока обязательство не исполнено полностью.","article_title":"Статья 323. Права кредитора при солидарной обязанности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"db39c35c77126d9c5bfa5a87ff19f85219c3bac48392cfcadd2beff81ad0a8b2"},{"code_id":"GK_RF","article_number":"324","version_date":"1994-11-30","article_text":"В случае солидарной обязанности должник не вправе выдвигать против требования кредитора возражения, основанные на таких отношениях других должников с кредитором, в которых данный должник не участвует.","article_title":"Статья 324. Возражения против требований кредитора при солидарной обязанности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"834e974e833e91bc3eb7673bcc307a841e7d5b9811d7fb8986535d6ffaeffa22"},{"code_id":"GK_RF","article_number":"325","version_date":"1994-11-30","article_text":"1. Исполнение солидарной обязанности полностью одним из должников освобождает остальных должников от исполнения кредитору.\n\n2. Если иное не вытекает из отношений между солидарными должниками:\n\n1) должник, исполнивший солидарную обязанность, имеет право регрессного требования к остальным должникам в равных долях за вычетом доли, падающей на него самого;\n\n2) неуплаченное одним из солидарных должников должнику, исполнившему солидарную обязанность, падает в равной доле на этого должника и на остальных должников.\n\n3. Правила настоящей статьи применяются соответственно при прекращении солидарного обязательства зачетом встречного требования одного из должников.","article_title":"Статья 325. Исполнение солидарной обязанности одним из должников","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b1a1769a52382dfba531763ea373e74f77a19999903e7e1d34eecbe1fa77551"},{"code_id":"GK_RF","article_number":"326","version_date":"1994-11-30","article_text":"1. При солидарности требования любой из солидарных кредиторов вправе предъявить к должнику требование в полном объеме.\n\nДо предъявления требования одним из солидарных кредиторов должник вправе исполнять обязательство любому из них по своему усмотрению.\n\n2. Должник не вправе выдвигать против требования одного из солидарных кредиторов возражения, основанные на таких отношениях должника с другим солидарным кредитором, в которых данный кредитор не участвует.\n\n3. Исполнение обязательства полностью одному из солидарных кредиторов освобождает должника от исполнения остальным кредиторам.\n\n4. Солидарный кредитор, получивший исполнение от должника, обязан возместить причитающееся другим кредиторам в равных долях, если иное не вытекает из отношений между ними.","article_title":"Статья 326. Солидарные требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"388f9a7b8d228a45da85e3aa8be71dd1af39e06c9ec36bab331c6b1ad7a8a216"},{"code_id":"GK_RF","article_number":"327","version_date":"1994-11-30","article_text":"1. Должник вправе внести причитающиеся с него деньги или ценные бумаги в депозит нотариуса, а в случаях, установленных законом, в депозит суда - если обязательство не может быть исполнено должником вследствие:\n\n1) отсутствия кредитора или лица, уполномоченного им принять исполнение, в месте, где обязательство должно быть исполнено;\n\n2) недееспособности кредитора и отсутствия у него представителя;\n\n3) очевидного отсутствия определенности по поводу того, кто является кредитором по обязательству, в частности в связи со спором по этому поводу между кредитором и другими лицами;\n\n4) уклонения кредитора от принятия исполнения или иной просрочки с его стороны.\n\n2. Внесение денежной суммы или ценных бумаг в депозит нотариуса или суда считается исполнением обязательства.\n\nНотариус или суд, в депозит которого внесены деньги или ценные бумаги, извещает об этом кредитора.","article_title":"Статья 327. Исполнение обязательства внесением долга в депозит","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ffbc617dee40d908fe8117032e572b56d7c26494b6c1b5cd0443625f8ecec7cf"},{"code_id":"GK_RF","article_number":"327.1","version_date":"1994-11-30","article_text":"Исполнение обязанностей, а равно и осуществление, изменение и прекращение определенных прав по договорному обязательству, может быть обусловлено совершением или несовершением одной из сторон обязательства определенных действий либо наступлением иных обстоятельств, предусмотренных договором, в том числе полностью зависящих от воли одной из сторон.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 327.1. Обусловленное исполнение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d903ca0bd9b1f381256737b11da76018515900a57bd6a7e45f3974394acb39b"},{"code_id":"GK_RF","article_number":"328","version_date":"1994-11-30","article_text":"1. Встречным признается исполнение обязательства одной из сторон, которое обусловлено исполнением другой стороной своих обязательств.\n\n2. В случае непредоставления обязанной стороной предусмотренного договором исполнения обязательства либо при наличии обстоятельств, очевидно свидетельствующих о том, что такое исполнение не будет произведено в установленный срок, сторона, на которой лежит встречное исполнение, вправе приостановить исполнение своего обязательства или отказаться от исполнения этого обязательства и потребовать возмещения убытков.\n\nЕсли предусмотренное договором исполнение обязательства произведено не в полном объеме, сторона, на которой лежит встречное исполнение, вправе приостановить исполнение своего обязательства или отказаться от исполнения в части, соответствующей непредоставленному исполнению.\n\n3. Ни одна из сторон обязательства, по условиям которого предусмотрено встречное исполнение, не вправе требовать по суду исполнения, не предоставив причитающегося с нее по обязательству другой стороне.\n\n4. Правила, предусмотренные пунктами 2 и 3 настоящей статьи, применяются, если законом или договором не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 328. Встречное исполнение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"73ae8f7a75f50567a8c2ec86f678e602edb92e71fefc329e0d511aaad21ac0b8"},{"code_id":"GK_RF","article_number":"329","version_date":"1994-11-30","article_text":"1. Исполнение обязательств может обеспечиваться неустойкой, залогом, удержанием вещи должника, поручительством, независимой гарантией, задатком, обеспечительным платежом и другими способами, предусмотренными законом или договором.\n\n2. Недействительность соглашения об обеспечении исполнения обязательства не влечет недействительности соглашения, из которого возникло основное обязательство.\n\n3. При недействительности соглашения, из которого возникло основное обязательство, обеспеченными считаются связанные с последствиями такой недействительности обязанности по возврату имущества, полученного по основному обязательству.\n\n4. Прекращение основного обязательства влечет прекращение обеспечивающего его обязательства, если иное не предусмотрено законом или договором.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 329. Способы обеспечения исполнения обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2ba6a86838e5d94005ab87aef1c30b1dd76ee13b97126c05a23634b93db244e"},{"code_id":"GK_RF","article_number":"33","version_date":"1994-11-30","article_text":"Попечители несовершеннолетних граждан и граждан, дееспособность которых ограничена вследствие психического расстройства, оказывают подопечным содействие в осуществлении ими своих прав и исполнении обязанностей, а также охраняют их от злоупотреблений со стороны третьих лиц.\n\n(Пункт в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 33. Попечительство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"747e4ab2796d021a1dbdf818478f69a56e35ea1b4ed5efe1632caa188cd7ba12"},{"code_id":"GK_RF","article_number":"330","version_date":"1994-11-30","article_text":"1. Неустойкой (штрафом, пеней) признается определенная законом или договором денежная сумма, которую должник обязан уплатить кредитору в случае неисполнения или ненадлежащего исполнения обязательства, в частности в случае просрочки исполнения. По требованию об уплате неустойки кредитор не обязан доказывать причинение ему убытков.\n\n2. Кредитор не вправе требовать уплаты неустойки, если должник не несет ответственности за неисполнение или ненадлежащее исполнение обязательства.","article_title":"Статья 330. Понятие неустойки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7f6335e2583a181aec84a5b421f60eedb4cd5494dbcbc0ecdb8e371a3107ca5"},{"code_id":"GK_RF","article_number":"331","version_date":"1994-11-30","article_text":"Соглашение о неустойке должно быть совершено в письменной форме независимо от формы основного обязательства.\n\nНесоблюдение письменной формы влечет недействительность соглашения о неустойке.","article_title":"Статья 331. Форма соглашения о неустойке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1afba1ba8f418e723f9843658a2c8024f4d7353ab8fa93bddd10e8be45761297"},{"code_id":"GK_RF","article_number":"332","version_date":"1994-11-30","article_text":"1. Кредитор вправе требовать уплаты неустойки, определенной законом (законной неустойки), независимо от того, предусмотрена ли обязанность ее уплаты соглашением сторон.\n\n2. Размер законной неустойки может быть увеличен соглашением сторон, если закон этого не запрещает.","article_title":"Статья 332. Законная неустойка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6dc607d3e8c14554e46bd543670eeaea44f27113390697c368c3dc4cc1751bb"},{"code_id":"GK_RF","article_number":"333","version_date":"1994-11-30","article_text":"1. Если подлежащая уплате неустойка явно несоразмерна последствиям нарушения обязательства, суд вправе уменьшить неустойку. Если обязательство нарушено лицом, осуществляющим предпринимательскую деятельность, суд вправе уменьшить неустойку при условии заявления должника о таком уменьшении.\n\n2. Уменьшение неустойки, определенной договором и подлежащей уплате лицом, осуществляющим предпринимательскую деятельность, допускается в исключительных случаях, если будет доказано, что взыскание неустойки в предусмотренном договором размере может привести к получению кредитором необоснованной выгоды.\n\n3. Правила настоящей статьи не затрагивают право должника на уменьшение размера его ответственности на основании статьи 404 настоящего Кодекса и право кредитора на возмещение убытков в случаях, предусмотренных статьей 394 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n(Параграф в редакции Федерального закона от 21.12.2013 № 367-ФЗ)\n\n1. Общие положения о залоге","article_title":"Статья 333. Уменьшение неустойки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f11cf91b933d751fdc3eb2dca3ff7c116acf121ccee21a19b17f2e0372f55f42"},{"code_id":"GK_RF","article_number":"334","version_date":"1994-11-30","article_text":"1. В силу залога кредитор по обеспеченному залогом обязательству (залогодержатель) имеет право в случае неисполнения или ненадлежащего исполнения должником этого обязательства получить удовлетворение из стоимости заложенного имущества (предмета залога) преимущественно перед другими кредиторами лица, которому принадлежит заложенное имущество (залогодателя).\n\nВ случаях и в порядке, которые предусмотрены законом, требование залогодержателя может быть удовлетворено путем передачи предмета залога залогодержателю (оставления у залогодержателя).\n\n2. Залогодержатель преимущественно перед другими кредиторами залогодателя вправе получить удовлетворение обеспеченного залогом требования также за счет:\n\nстрахового возмещения за утрату или повреждение заложенного имущества независимо от того, в чью пользу оно застраховано, если только утрата или повреждение произошли не по причинам, за которые залогодержатель отвечает;\n\nпричитающегося залогодателю возмещения, предоставляемого взамен заложенного имущества, в частности если право собственности залогодателя на имущество, являющееся предметом залога, прекращается по основаниям и в порядке, которые установлены законом, вследствие изъятия (выкупа) для государственных или муниципальных нужд, реквизиции или национализации, а также в иных случаях, предусмотренных законом;\n\nпричитающихся залогодателю или залогодержателю доходов от использования заложенного имущества третьими лицами;\n\nимущества, причитающегося залогодателю при исполнении третьим лицом обязательства, право требовать исполнения которого является предметом залога.\n\nВ случаях, указанных в абзацах втором - пятом настоящего пункта, залогодержатель вправе требовать причитающиеся ему денежную сумму или иное имущество непосредственно от обязанного лица, если иное не предусмотрено законом или договором.\n\n3. Если иное не предусмотрено законом или договором, при недостаточности суммы, вырученной в результате обращения взыскания на заложенное имущество, для погашения требования залогодержатель вправе удовлетворить свое требование в непогашенной части за счет иного имущества должника, не пользуясь преимуществом, основанным на залоге.\n\nЕсли сумма, вырученная в результате обращения взыскания на заложенное имущество, превышает размер обеспеченного залогом требования залогодержателя, разница возвращается залогодателю. Соглашение об отказе залогодателя от права на получение указанной разницы ничтожно.\n\n4. К отдельным видам залога (статьи 357 - 35817) применяются общие положения о залоге, если иное не предусмотрено правилами настоящего Кодекса об эт\n\nих видах залога.\n\nК залогу недвижимого имущества (ипотеке) применяются правила настоящего Кодекса о вещных правах, а в части, не урегулированной указанными правилами и законом об ипотеке, общие положения о залоге.\n\n5. Если иное не вытекает из существа отношений залога, кредитор или иное управомоченное лицо, в чьих интересах был наложен запрет на распоряжение имуществом (статья 1741), обладает правами и обязанностями залогодержателя в отношении этого имущества с момента вступления в силу решения суда, которым требования таких кредитора или иного управомоченного лица были удовлетворены. Очередность удовлетворения указанных требований определяется в соответствии с положениями статьи 3421 настоящего Кодекса по дате, на которую соответствующий запрет считается возникшим.","article_title":"Статья 334. Понятие залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7a5979b60be3e44c9ba5c1210e7169d3954230f36dadfafff302b221ead926f"},{"code_id":"GK_RF","article_number":"334.1","version_date":"1994-11-30","article_text":"1. Залог между залогодателем и залогодержателем возникает на основании договора. В случаях, установленных законом, залог возникает при наступлении указанных в законе обстоятельств (залог на основании закона).\n\n2. Правила настоящего Кодекса о залоге на основании договора соответственно применяются к залогу, возникшему на основании закона, если законом не установлено иное.\n\n3. В случае возникновения залога на основании закона залогодатель и залогодержатель вправе заключить соглашение, регулирующее их отношения. К такому соглашению применяются правила настоящего Кодекса о форме договора залога.","article_title":"Статья 334.1. Основания возникновения залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0170f0addca6440ed5149eed4f92d656cd0a5fa510bc4bed7d8f6022ac32a220"},{"code_id":"GK_RF","article_number":"335","version_date":"1994-11-30","article_text":"1. Залогодателем может быть как сам должник, так и третье лицо.\n\nВ случае, когда залогодателем является третье лицо, к отношениям между залогодателем, должником и залогодержателем применяются правила статей 364 - 367 настоящего Кодекса, если законом или соглашением между соответствующими лицами не предусмотрено иное.\n\n2. Право передачи вещи в залог принадлежит собственнику вещи. Лицо, имеющее иное вещное право, может передавать вещь в залог в случаях, предусмотренных настоящим Кодексом.\n\nЕсли вещь передана в залог залогодержателю лицом, которое не являлось ее собственником или иным образом не было надлежаще управомочено распоряжаться имуществом, о чем залогодержатель не знал и не должен был знать (добросовестный залогодержатель), собственник заложенного имущества имеет права и несет обязанности залогодателя, предусмотренные настоящим Кодексом, другими законами и договором залога.\n\nПравила, предусмотренные абзацем вторым настоящего пункта, не применяются, если вещь, переданная в залог, была утеряна до этого собственником или лицом, которому вещь была передана собственником во владение, либо была похищена у того или другого, либо выбыла из их владения иным путем помимо их воли.\n\n3. Если предметом залога является имущество, на отчуждение которого требуется согласие или разрешение другого лица либо уполномоченного органа, такое же согласие или такое же разрешение необходимо для передачи этого имущества в залог, за исключением случаев, когда залог возникает в силу закона.\n\n4. В случае, если имущество залогодателя, являющееся предметом залога, перешло в порядке правопреемства к нескольким лицам, каждый из правопреемников (приобретателей имущества) несет вытекающие из залога последствия неисполнения обеспеченного залогом обязательства соразмерно перешедшей к нему части указанного имущества. Если предмет залога неделим или по иным основаниям остается в общей собственности правопреемников, они становятся солидарными созалогодателями.","article_title":"Статья 335. Залогодатель","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3d59ae76edfb1e58a6ed1cb7b931f1c791dda39184126cfe58f532468e0d260"},{"code_id":"GK_RF","article_number":"335.1","version_date":"1994-11-30","article_text":"1. В случаях, предусмотренных законом или договором, предмет залога может находиться в залоге у нескольких лиц, имеющих на него равные по старшинству права залогодержателей (созалогодержатели), в обеспечение исполнения разных обязательств, по которым созалогодержатели являются самостоятельными кредиторами.\n\nЕсли иное не установлено законом или соглашением между созалогодержателями, каждый из них самостоятельно осуществляет права и обязанности залогодержателя. При обращении взыскания на предмет залога, находящийся в залоге у созалогодержателей, применяются правила пунктов 2 и 6 статьи 3421 настоящего Кодекса.\n\nДенежные суммы, вырученные от реализации предмета залога, распределяются между созалогодержателями пропорционально размерам их требований, обеспеченных залогом, если иное не предусмотрено соглашением между ними или не вытекает из существа отношений между созалогодержателями.\n\n2. Если иное не предусмотрено законом или договором, солидарные или долевые кредиторы по обязательству, исполнение которого обеспечено залогом, являются солидарными созалогодержателями по такому залогу. При обращении взыскания на предмет залога, находящийся в залоге у солидарных созалогодержателей, применяются правила пункта 6 статьи 3421 настоящего Кодекса.\n\nДенежные суммы, вырученные от реализации предмета залога, распределяются между созалогодержателями, являющимися солидарными кредиторами по основному обязательству, в порядке, установленном пунктом 4 статьи 326 настоящего Кодекса. Денежные суммы, вырученные от реализации предмета залога, распределяются между созалогодержателями, являющимися долевыми кредиторами по основному обязательству, пропорционально размерам их требований, обеспеченных залогом, если иное не предусмотрено договором между ними.","article_title":"Статья 335.1. Созалогодержатели","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"594709b6b91ea41d60321926ca826566a2864becfa67d6d9ad30ff945346ffbe"},{"code_id":"GK_RF","article_number":"336","version_date":"1994-11-30","article_text":"1. Предметом залога может быть всякое имущество, в том числе вещи и имущественные права, за исключением имущества, на которое не допускается обращение взыскания, требований, неразрывно связанных с личностью кредитора, в частности требований об алиментах, о возмещении вреда, причиненного жизни или здоровью, и иных прав, уступка которых другому лицу запрещена законом.\n\nЗалог отдельных видов имущества может быть ограничен или запрещен законом.\n\n2. Договором залога или в отношении залога, возникающего на основании закона, законом может быть предусмотрен залог имущества, которое залогодатель приобретет в будущем.\n\n3. На полученные в результате использования заложенного имущества плоды, продукцию и доходы залог распространяется в случаях, предусмотренных законом или договором.\n\n4. При заключении договора залога залогодатель обязан предупредить в письменной форме залогодержателя о всех известных ему к моменту заключения договора правах третьих лиц на предмет залога (вещных правах, правах, возникающих из договоров аренды, ссуды и т.п.). В случае неисполнения залогодателем этой обязанности залогодержатель вправе потребовать досрочного исполнения обеспеченного залогом обязательства или изменения условий договора залога, если иное не предусмотрено законом или договором.","article_title":"Статья 336. Предмет залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6280119419b1eefb70d1e840955a292aa2a20c02c6c982353eb3e8894d115067"},{"code_id":"GK_RF","article_number":"337","version_date":"1994-11-30","article_text":"Если иное не предусмотрено законом или договором, залог обеспечивает требование в том объеме, какой оно имеет к моменту удовлетворения, в частности проценты, неустойку, возмещение убытков, причиненных просрочкой исполнения, а также возмещение необходимых расходов залогодержателя на содержание предмета залога и связанных с обращением взыскания на предмет залога и его реализацией расходов.","article_title":"Статья 337. Обеспечиваемое залогом требование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"21dc1bdec1ecb98af37fb9cd09fa2a01024e9bf301c4a784b2ead54af45f122b"},{"code_id":"GK_RF","article_number":"338","version_date":"1994-11-30","article_text":"1. Заложенное имущество остается у залогодателя, если иное не предусмотрено настоящим Кодексом, другим законом или договором.\n\n2. Предмет залога может быть оставлен у залогодателя под замком и печатью залогодержателя.\n\nПредмет залога может быть оставлен у залогодателя с наложением знаков, свидетельствующих о залоге (твердый залог).\n\n3. Предмет залога, переданный залогодателем на время во владение или в пользование третьему лицу, считается оставленным у залогодателя.","article_title":"Статья 338. Владение предметом залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a62676de9b076efe4699692fbf937619714f7af313a70d4270c215a1bcedb1de"},{"code_id":"GK_RF","article_number":"339","version_date":"1994-11-30","article_text":"1. В договоре залога должны быть указаны предмет залога, существо, размер и срок исполнения обязательства, обеспечиваемого залогом. Условия, относящиеся к основному обязательству, считаются согласованными, если в договоре залога имеется отсылка к договору, из которого возникло или возникнет в будущем обеспечиваемое обязательство.\n\nСтороны могут предусмотреть в договоре залога условие о порядке реализации заложенного имущества, взыскание на которое обращено по решению суда, или условие о возможности обращения взыскания на заложенное имущество во внесудебном порядке.\n\n2. В договоре залога, залогодателем по которому является лицо, осуществляющее предпринимательскую деятельность, обязательство, обеспечиваемое залогом, включая будущее обязательство, может быть описано способом, позволяющим определить обязательство в качестве обязательства, обеспеченного залогом, на момент обращения взыскания, в том числе путем указания на обеспечение всех существующих и (или) будущих обязательств должника перед кредитором в пределах определенной суммы.\n\nВ договоре залога, залогодателем по которому является лицо, осуществляющее предпринимательскую деятельность, предмет залога может быть описан любым способом, позволяющим идентифицировать имущество в качестве предмета залога на момент обращения взыскания, в том числе путем указания на залог всего имущества залогодателя или определенной части его имущества либо на залог имущества определенных рода или вида.\n\n3. Договор залога должен быть заключен в простой письменной форме, если законом или соглашением сторон не установлена нотариальная форма.\n\nДоговор залога в обеспечение исполнения обязательств по договору, который должен быть нотариально удостоверен, подлежит нотариальному удостоверению.\n\nНесоблюдение правил, содержащихся в настоящем пункте, влечет недействительность договора залога.","article_title":"Статья 339. Условия и форма договора залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5d41b1f02b29fd778f82aba75f1a9382721337f709de664d510633c78f9c82da"},{"code_id":"GK_RF","article_number":"339.1","version_date":"1994-11-30","article_text":"1. Залог подлежит государственной регистрации и возникает с момента такой регистрации в следующих случаях:\n\n1) если в соответствии с законом права, закрепляющие принадлежность имущества определенному лицу, подлежат государственной регистрации (статья 81);\n\n2) если предметом залога являются права участника (учредителя) общества с ограниченной ответственностью (статья 35815).\n\n2. Записи о залоге ценных бумаг совершаются в соответствии с правилами настоящего Кодекса и других законов о ценных бумагах.\n\n3. Сведения о залоге прав по договору банковского счета учитываются в соответствии с правилами статьи 35811 настоящего Кодекса.\n\n4. Залог иного имущества, не относящегося к недвижимым вещам, помимо указанного в пунктах 1 - 3 настоящей статьи имущества, может быть учтен путем регистрации уведомлений о залоге, поступивших от залогодателя, залогодержателя или в случаях, установленных законодательством о нотариате, от другого лица, в реестре уведомлений о залоге такого имущества (реестр уведомлений о залоге движимого имущества). Реестр уведомлений о залоге движимого имущества ведется в порядке, установленном законодательством о нотариате.\n\nВ случае изменения или прекращения залога, в отношении которого зарегистрировано уведомление о залоге, залогодержатель обязан направить в порядке, установленном законодательством о нотариате, уведомление об изменении залога или об исключении сведений о залоге в течение трех рабочих дней с момента, когда он узнал или должен был узнать об изменении или о прекращении залога. В случаях, предусмотренных законодательством о нотариате, уведомление об изменении залога или об исключении сведений о залоге направляет иное указанное в законе лицо.\n\nЗалогодержатель в отношениях с третьими лицами вправе ссылаться на принадлежащее ему право залога только с момента совершения записи об учете залога, за исключением случаев, если третье лицо знало или должно было знать о существовании залога ранее этого. Отсутствие записи об учете не затрагивает отношения залогодателя с залогодержателем.","article_title":"Статья 339.1. Государственная регистрация и учет залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5bb7b059275d1c092cc48f26ecb878421c27994d87dce63e7e75b11a7b31241"},{"code_id":"GK_RF","article_number":"34","version_date":"1994-11-30","article_text":"Абзац. (Дополнение абзацем - Федеральный закон от 02.07.2013 № 167-ФЗ) (Утратил силу - Федеральный закон от 08.08.2024 № 237-ФЗ)\n\nПолномочия органа опеки и попечительства в отношении подопечного возлагаются на орган, который установил опеку или попечительство. При перемене места жительства подопечного полномочия органа опеки и попечительства возлагаются на орган опеки и попечительства по новому месту жительства подопечного в порядке, определенном Федеральным законом \"Об опеке и попечительстве\". (Дополнение абзацем - Федеральный закон от 24.04.2008 № 49-ФЗ)","article_title":"Статья 34. Органы опеки и попечительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a9a03a0fbfac040706bf795b731b3306e3186e188bb8b6bd6a127a3dd8f7be2"},{"code_id":"GK_RF","article_number":"340","version_date":"1994-11-30","article_text":"1. Стоимость предмета залога определяется по соглашению сторон, если иное не предусмотрено законом.\n\n2. Если иное не предусмотрено законом или договором, изменение рыночной стоимости предмета залога после заключения договора залога или возникновения залога в силу закона не является основанием для изменения или прекращения залога.\n\nУсловия договора, которые предусматривают в связи с последующим уменьшением рыночной стоимости предмета залога, обеспечивающего обязательство гражданина по возврату потребительского или ипотечного кредита, распространение залога на иное имущество, досрочный возврат кредита или иные неблагоприятные для залогодателя последствия, ничтожны.\n\n3. Если иное не предусмотрено законом, соглашением сторон или решением суда об обращении взыскания на заложенное имущество, согласованная сторонами стоимость предмета залога признается ценой реализации (начальной продажной ценой) предмета залога при обращении на него взыскания.","article_title":"Статья 340. Стоимость предмета залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb8cf6778202550c0e9e2bbce5f6d349491db9875b4bf7cfef8f43f8f01be042"},{"code_id":"GK_RF","article_number":"341","version_date":"1994-11-30","article_text":"1. Права залогодержателя в отношениях с залогодателем возникают с момента заключения договора залога, если иное не установлено договором, настоящим Кодексом и другими законами.\n\n2. Если предметом залога является имущество, которое будет создано или приобретено залогодателем в будущем, залог возникает у залогодержателя с момента создания или приобретения залогодателем соответствующего имущества, за исключением случая, когда законом или договором предусмотрено, что оно возникает в иной срок.\n\n3. Если основное обязательство, обеспечиваемое залогом, возникнет в будущем после заключения договора залога, залог возникает с момента, определенного договором, но не ранее возникновения этого обязательства. С момента заключения такого договора залога к отношениям сторон применяются положения статей 343 и 346 настоящего Кодекса.\n\n4. Законом в отношении залога недвижимого имущества может быть предусмотрено, что залог считается возникшим, существует и прекращается независимо от возникновения, существования и прекращения обеспеченного обязательства.","article_title":"Статья 341. Возникновение залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d36e8fef71490c0d5e6990ce5521598e092ba1c812fd4d74bd6f368826604bc"},{"code_id":"GK_RF","article_number":"342","version_date":"1994-11-30","article_text":"1. В случаях, если имущество, находящееся в залоге, становится предметом еще одного залога в обеспечение других требований (последующий залог), требования последующего залогодержателя удовлетворяются из стоимости этого имущества после требований предшествующих залогодержателей.\n\nСтаршинство залогов может быть изменено:\n\nсоглашением между залогодержателями;\n\nсоглашением между одним, несколькими или всеми залогодержателями и залогодателем.\n\nВо всяком случае указанные соглашения не затрагивают права третьих лиц, не являющихся сторонами указанных соглашений.\n\n2. Последующий залог допускается, если иное не установлено законом.\n\nЕсли предшествующий договор залога предусматривает условия, на которых может быть заключен последующий договор залога, такой договор залога должен быть заключен с соблюдением указанных условий. При нарушении указанных условий предшествующий залогодержатель вправе требовать от залогодателя возмещения причиненных этим убытков.\n\n3. Залогодатель обязан сообщать каждому последующему залогодержателю сведения о всех существующих залогах имущества, предусмотренные пунктом 1 статьи 339 настоящего Кодекса, и отвечает за убытки, причиненные последующим залогодержателям вследствие невыполнения этой обязанности, если не докажет, что залогодержатель знал или должен был знать о предшествующих залогах.\n\n4. Залогодатель, заключивший последующий договор залога, незамедлительно должен уведомить об этом залогодержателей по предшествующим залогам и по их требованию сообщить сведения о последующем залоге, предусмотренные пунктом 1 статьи 339 настоящего Кодекса.\n\n5. Если последующий договор залога заключен с нарушением условий, предусмотренных для него предшествующим договором залога, о чем залогодержатель по последующему договору знал или должен был знать, его требования к залогодателю удовлетворяются с учетом условий предшествующего договора залога.\n\n6. Изменение предшествующего договора залога после заключения последующего договора залога, если последующий договор залога заключен с соблюдением условий, предусмотренных для него предшествующим договором залога, или такие условия не были предусмотрены предшествующим договором залога, не затрагивает права последующего залогодержателя при условии, что такое изменение влечет ухудшение обеспечения его требования и произведено без согласия последующего залогодержателя.","article_title":"Статья 342. Соотношение предшествующего и последующего залогов (старшинство залогов)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0b63caa642c06e27ae23a2a60bf6051294e6633e3b48a8f7bacaab1baa299d27"},{"code_id":"GK_RF","article_number":"342.1","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено настоящим Кодексом или другим законом, очередность удовлетворения требований залогодержателей устанавливается в зависимости от момента возникновения каждого залога.\n\nНезависимо от момента возникновения залога, если будет доказано, что залогодержатель на момент заключения договора или на момент возникновения обстоятельств, с которыми закон связывает возникновение залога, знал или должен был знать о наличии предшествующего залогодержателя, требования такого предшествующего залогодержателя удовлетворяются преимущественно.\n\n2. В случае обращения взыскания на заложенное имущество предшествующим залогодержателем последующий залогодержатель вправе потребовать от должника досрочного исполнения обязательства, обеспеченного последующим залогом, и в случае его неисполнения обратить взыскание на заложенное имущество одновременно с предшествующим залогодержателем. Договором между залогодателем и последующим залогодержателем может быть ограничено право такого залогодержателя потребовать от должника досрочного исполнения обязательства, обеспеченного последующим залогом.\n\n3. Требование, обеспеченное последующим залогом, не подлежит досрочному удовлетворению, если оставшегося после обращения взыскания предшествующим залогодержателем заложенного имущества будет достаточно для удовлетворения требования последующего залогодержателя.\n\n4. Если последующий залогодержатель не воспользовался правом потребовать досрочного исполнения обязательства или данное право было ограничено соглашением в соответствии с пунктом 2 настоящей статьи, последующий залог прекращается, за исключением случаев, предусмотренных пунктом 3 настоящей статьи.\n\n5. Если в отношении заложенного имущества, не относящегося к недвижимым вещам, заключены два и более договора о залоге или совершены иные сделки, повлекшие возникновение залога, и невозможно установить, какая из указанных сделок совершена ранее, требования залогодержателей по таким залогам удовлетворяются пропорционально размерам обеспеченных залогом обязательств.\n\n6. В случае обращения взыскания на заложенное имущество по требованиям, обеспеченным последующим залогом, предшествующий залогодержатель вправе потребовать одновременно досрочного исполнения обеспеченного залогом обязательства и обращения взыскания на это имущество. Если залогодержатель по предшествующему договору залога не воспользовался данным правом, имущество, на которое обращено взыскание по требованиям, обеспеченным последующим залогом, переходит к его приобретателю с обременением предшествующим залогом.\n\n7. До обращения взыскания на имущество, залогом которого обеспечены требования по предшествующему и последующему залогам, залогодержатель, имеющий намерение предъявить свои требования к взысканию, обязан уведомить об этом в письменной форме всех других известных ему залогодержателей этого же имущества.\n\nЗалогодатель, к которому предъявлено требование об обращении взыскания на заложенное имущество одним из залогодержателей, обязан уведомить об этом в письменной форме всех других залогодержателей этого же имущества.\n\n8. После распределения сумм, вырученных от реализации заложенного имущества, между всеми залогодержателями реализованного заложенного имущества, заявившими свои требования к взысканию, в порядке очередности распределяются суммы неустойки, убытков и иных штрафных санкций, подлежащих уплате залогод\n\nержателю в соответствии с условиями обеспеченного обязательства. Иная очередность распределения сумм неустойки, убытков и иных штрафных санкций может быть предусмотрена в соответствии с законами о ценных бумагах.\n\n9. Правила, установленные настоящей статьей, не применяются, если залогодержателем по предшествующему и последующему залогам является одно и то же лицо. В этом случае требования, обеспеченные каждым из залогов, удовлетворяются в порядке очередности, соответствующей срокам исполнения обеспеченных залогом обязательств, если законом или соглашением сторон не предусмотрено иное.\n\n10. В случаях, если заложенное имущество, в отношении которого ведется учет залогов в соответствии с пунктом 4 статьи 3391 настоящего Кодекса, является предметом нескольких залогов, требования залогодержателя, обеспеченные залогом, запись об учете которого совершена ранее, удовлетворяются преимущественно перед требованиями залогодержателя, обеспеченными залогом того же имущества, запись об учете которого не совершена в установленном законом порядке или совершена позднее, независимо от того, какой залог возник ранее. Иной порядок удовлетворения требований залогодержателей может быть предусмотрен в соответствии с законами о ценных бумагах.","article_title":"Статья 342.1. Очередность удовлетворения требований залогодержателей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"288738714f316073fe74ebf62dd21bfd60f0df88701dca6cb1bf54cb03faf922"},{"code_id":"GK_RF","article_number":"343","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, залогодатель или залогодержатель в зависимости от того, у кого из них находится заложенное имущество (статья 338), обязан:\n\n1) страховать от рисков утраты и повреждения за счет залогодателя заложенное имущество на сумму не ниже размера обеспеченного залогом требования;\n\n2) пользоваться и распоряжаться заложенным имуществом в соответствии с правилами статьи 346 настоящего Кодекса;\n\n3) не совершать действия, которые могут повлечь утрату заложенного имущества или уменьшение его стоимости, и принимать меры, необходимые для обеспечения сохранности заложенного имущества;\n\n4) принимать меры, необходимые для защиты заложенного имущества от посягательств и требований со стороны третьих лиц;\n\n5) немедленно уведомлять другую сторону о возникновении угрозы утраты или повреждения заложенного имущества, о притязаниях третьих лиц на это имущество, о нарушениях третьими лицами прав на это имущество.\n\n2. Залогодержатель и залогодатель вправе проверять по документам и фактически наличие, количество, состояние и условия хранения заложенного имущества, находящегося у другой стороны, не создавая при этом неоправданных помех для правомерного использования заложенного имущества.\n\n3. При грубом нарушении залогодержателем или залогодателем указанных в пункте 1 настоящей статьи обязанностей, создающем угрозу утраты или повреждения заложенного имущества, залогодатель вправе потребовать досрочного прекращения залога, а залогодержатель - досрочного исполнения обязательства, обеспеченного залогом, и в случае его неисполнения - обращения взыскания на заложенное имущество.","article_title":"Статья 343. Содержание и сохранность заложенного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f44f38ea6c6ecf2c9182550f0be8b727c388226ad8ad9ce3437a71abe86f320e"},{"code_id":"GK_RF","article_number":"344","version_date":"1994-11-30","article_text":"1. Залогодатель несет риск случайной гибели или случайного повреждения заложенного имущества, если иное не предусмотрено договором залога.\n\n2. Залогодержатель отвечает перед залогодателем за полную или частичную утрату или повреждение переданного ему предмета залога, если не докажет, что может быть освобожден от ответственности в соответствии со статьей 401 настоящего Кодекса.\n\nЗалогодержатель отвечает за утрату предмета залога в размере его рыночной стоимости, а за его повреждение в размере суммы, на которую эта стоимость понизилась, независимо от суммы, в которую был оценен предмет залога по договору залога.\n\nЕсли в результате повреждения предмета залога он изменился настолько, что не может быть использован по прямому назначению, залогодатель вправе отказаться от него и потребовать от залогодержателя возмещение за его утрату.\n\nДоговором может быть предусмотрена обязанность залогодержателя возместить залогодателю и иные убытки, причиненные утратой или повреждением предмета залога.\n\n3. Залогодатель, являющийся должником по обеспеченному залогом обязательству, вправе зачесть требование к залогодержателю о возмещении убытков, причиненных утратой или повреждением предмета залога, в погашение обязательства, обеспеченного залогом, в том числе тогда, когда срок исполнения этого обязательства еще не наступил и досрочное исполнение обязательства не допускается.","article_title":"Статья 344. Последствия утраты или повреждения заложенного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72108ae57fb0d5447195001c2d9f5cc9a0196366c24138b8457950069d3fb676"},{"code_id":"GK_RF","article_number":"345","version_date":"1994-11-30","article_text":"1. По соглашению залогодателя и залогодержателя предмет залога может быть заменен другим имуществом.\n\n2. Независимо от согласия на это залогодателя или залогодержателя считаются находящимися в залоге:\n\n1) новое имущество, которое принадлежит залогодателю и создано либо возникло в результате переработки или иного изменения заложенного имущества;\n\n2) имущество, предоставленное залогодателю взамен предмета залога в случае его изъятия (выкупа) для государственных или муниципальных нужд, реквизиции или национализации по основаниям и в порядке, которые установлены законом, а также право требовать предоставления имущества взамен предмета залога по указанным основаниям;\n\n3) имущество, за исключением денежных средств, переданное залогодателю-кредитору его должником, в случае залога права (требования);\n\n4) иное имущество в случаях, установленных законом.\n\n3. Если замена предмета залога другим имуществом в случае, предусмотренном подпунктом 1 пункта 2 настоящей статьи, произошла в результате действий залогодателя, совершенных в нарушение договора залога, залогодержатель вправе потребовать досрочного исполнения обязательства, обеспеченного залогом, а при его неисполнении - обращения взыскания на новый предмет залога.\n\n4. Если предмет залога погиб или поврежден по обстоятельствам, за которые залогодержатель не отвечает, залогодатель в разумный срок вправе восстановить предмет залога или заменить его другим равноценным имуществом при условии, что договором не предусмотрено иное.\n\nЗалогодатель, намеревающийся воспользоваться правом на восстановление или замену предмета залога, незамедлительно обязан уведомить об этом в письменной форме залогодержателя. Залогодержатель вправе отказаться в письменной форме в срок, установленный договором залога, или, если такой срок не установлен, в разумный срок после получения уведомления от восстановления или замены предмета залога при условии, что прежний и новый предметы залога неравноценны.\n\n5. В случаях, указанных в пункте 2 настоящей статьи, имущество, которое заменяет предмет залога, в том числе право (требование), считается находящимся в залоге вместо прежнего предмета залога с момента возникновения на него прав залогодателя или с момента возникновения права, за исключением случаев, если в соответствии с законом возникновение, переход и обременение прав требуют государственной регистрации.\n\nУсловия договора залога, а также иных соглашений, заключенных сторонами в отношении прежнего предмета залога, применяются к правам и обязанностям сторон в отношении нового предмета залога в той мере, в какой они не противоречат существу (свойствам) этого предмета залога.\n\nВ случае замены предмета залога старшинство прав залогодержателей, в том числе возникших до предоставления имущества в качестве замены прежнего предмета залога, не изменяется.\n\n6. Вместо замены предмета залога стороны вправе заключить новый договор залога. С момента возникновения у залогодержателя залога на новый предмет залога прежний договор залога прекращается.\n\n7. Договором залога могут быть предусмотрены случаи, в которых залогодатель вправе заменять предмет залога без согласия залогодержателя.","article_title":"Статья 345. Замена и восстановление предмета залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9468c227ce7098ebd02e1c084c1aff887c0bce89deef0782ac11a4a0191daab"},{"code_id":"GK_RF","article_number":"346","version_date":"1994-11-30","article_text":"1. Залогодатель, у которого остается предмет залога, вправе пользоваться, если иное не предусмотрено договором и не вытекает из существа залога, предметом залога в соответствии с его назначением, в том числе извлекать из него плоды и доходы.\n\n2. Залогодатель не вправе отчуждать предмет залога без согласия залогодержателя, если иное не предусмотрено законом или договором и не вытекает из существа залога.\n\nВ случае отчуждения залогодателем заложенного имущества без согласия залогодержателя применяются правила, установленные подпунктом 3 пункта 2 статьи 351, подпунктом 2 пункта 1 статьи 352, статьей 353 настоящего Кодекса. Залогодатель также обязан возместить убытки, причиненные залогодержателю в результате отчуждения заложенного имущества.\n\n3. Если иное не предусмотрено законом или договором залога, залогодатель, у которого осталось заложенное имущество, вправе передавать без согласия залогодержателя заложенное имущество во временное владение или пользование другим лицам. В этом случае залогодатель не освобождается от исполнения обязанностей по договору залога.\n\nЕсли для передачи залогодателем заложенного имущества во временное владение или пользование другим лицам необходимо согласие залогодержателя, при нарушении залогодателем этого условия применяются правила, установленные подпунктом 3 пункта 2 статьи 351 настоящего Кодекса.\n\n4. В случае обращения залогодержателем взыскания на заложенное имущество вещные права, право, возникающее из договора аренды, иные права, возникающие из сделок по предоставлению имущества во владение или в пользование, которые предоставлены залогодателем третьим лицам без согласия залогодержателя, прекращаются с момента вступления в законную силу решения суда об обращении взыскания на заложенное имущество или, если требование залогодержателя удовлетворяется без обращения в суд (во внесудебном порядке), с момента возникновения права собственности на заложенное имущество у его приобретателя при условии, что приобретатель не согласится с сохранением указанных прав.\n\n5. Залогодержатель вправе пользоваться переданным ему предметом залога только в случаях, предусмотренных договором, регулярно представляя залогодателю отчет о пользовании. По договору на залогодержателя может быть возложена обязанность извлекать из предмета залога плоды и доходы в целях погашения основного обязательства или в интересах залогодателя.","article_title":"Статья 346. Пользование и распоряжение предметом залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2d5576fa2bb17baa25f2f0a0fb481d46aa1138577113a3c31da9fb74aba8654"},{"code_id":"GK_RF","article_number":"347","version_date":"1994-11-30","article_text":"1. С момента возникновения залога залогодержатель, у которого находилось или должно было находиться заложенное имущество, вправе истребовать его из чужого незаконного владения, в том числе из владения залогодателя.\n\n2. В случаях, если залогодержателю предоставлено право пользоваться переданным ему предметом залога, он может требовать от других лиц, в том числе от залогодателя, устранения всяких нарушений его права, хотя бы эти нарушения и не были соединены с лишением владения.\n\nЗалогодержатель также вправе требовать освобождения заложенного имущества от ареста (исключения его из описи) в связи с обращением на него взыскания в порядке исполнительного производства.","article_title":"Статья 347. Защита залогодержателем своих прав на предмет залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"07e0709ba822a4856fae9a3052fb5c864aa6f6fa5a16af4623694c76def34828"},{"code_id":"GK_RF","article_number":"348","version_date":"1994-11-30","article_text":"1. Взыскание на заложенное имущество для удовлетворения требований залогодержателя может быть обращено в случае неисполнения или ненадлежащего исполнения должником обеспеченного залогом обязательства.\n\n2. Обращение взыскания на заложенное имущество не допускается, если допущенное должником нарушение обеспеченного залогом обязательства незначительно и размер требований залогодержателя вследствие этого явно несоразмерен стоимости заложенного имущества. Если не доказано иное, предполагается, что нарушение обеспеченного залогом обязательства незначительно и размер требований залогодержателя явно несоразмерен стоимости заложенного имущества при условии, что одновременно соблюдены следующие условия:\n\n1) сумма неисполненного обязательства составляет менее чем пять процентов от размера стоимости заложенного имущества;\n\n2) период просрочки исполнения обязательства, обеспеченного залогом, составляет менее чем три месяца.\n\n3. Если договором залога не предусмотрено иное, обращение взыскания на имущество, заложенное для обеспечения обязательства, исполняемого периодическими платежами, допускается при систематическом нарушении сроков их внесения, то есть при нарушении сроков внесения платежей более чем три раза в течение двенадцати месяцев, предшествующих дате обращения в суд или дате направления уведомления об обращении взыскания на заложенное имущество во внесудебном порядке, даже при условии, что каждая просрочка незначительна.\n\n4. Должник и являющийся третьим лицом залогодатель вправе прекратить в любое время до реализации предмета залога обращение на него взыскания и его реализацию, исполнив обеспеченное залогом обязательство или ту его часть, исполнение которой просрочено. Соглашение, ограничивающее это право, ничтожно.","article_title":"Статья 348. Основания обращения взыскания на заложенное имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ac6747be4e95641a7f2e1a40798831828fe97aa510e1c4f8cdff9f5e7523450"},{"code_id":"GK_RF","article_number":"349","version_date":"1994-11-30","article_text":"1. Обращение взыскания на заложенное имущество осуществляется по решению суда, если соглашением залогодателя и залогодержателя не предусмотрен внесудебный порядок обращения взыскания на заложенное имущество.\n\nЕсли соглашением сторон предусмотрен внесудебный порядок обращения взыскания на заложенное имущество, залогодержатель вправе предъявить в суд требование об обращении взыскания на заложенное имущество. В этом случае дополнительные расходы, связанные с обращением взыскания на заложенное имущество в судебном порядке, возлагаются на залогодержателя, если он не докажет, что обращение взыскания на предмет залога или реализация предмета залога в соответствии с соглашением о внесудебном порядке обращения взыскания не были осуществлены в связи с действиями залогодателя или третьих лиц.\n\nПри обращении взыскания и реализации заложенного имущества залогодержателем и иными лицами должны быть приняты меры, необходимые для получения наибольшей выручки от продажи предмета залога. Лицо, которому причинены убытки неисполнением указанной обязанности, вправе потребовать их возмещения.\n\n2. Удовлетворение требования залогодержателя за счет заложенного имущества без обращения в суд (во внесудебном порядке) допускается на основании соглашения залогодателя с залогодержателем, если иное не предусмотрено законом.\n\n3. Взыскание на предмет залога может быть обращено только по решению суда в случаях, если:\n\nпредметом залога является единственное жилое помещение, принадлежащее на праве собственности гражданину, за исключением случаев заключения после возникновения оснований для обращения взыскания соглашения об обращении взыскания во внесудебном порядке;\n\nпредметом залога является имущество, имеющее значительную историческую, художественную или иную культурную ценность для общества;\n\nзалогодатель - физическое лицо в установленном порядке признано безвестно отсутствующим;\n\nзаложенное имущество является предметом предшествующего и последующего залогов, при которых применяются разный порядок обращения взыскания на предмет залога или разные способы реализации заложенного имущества, если соглашением между предшествующим и последующим залогодержателями не предусмотрено иное;\n\nимущество заложено в обеспечение исполнения разных обязательств нескольким залогодержателям, за исключением случая, когда соглашением всех созалогодержателей с залогодателем предусмотрен внесудебный порядок обращения взыскания.\n\nЗаконом могут быть предусмотрены иные случаи, в которых обращение взыскания на заложенное имущество во внесудебном порядке не допускается.\n\nСоглашения, заключенные с нарушением требований настоящего пункта, ничтожны.\n\n4. Стороны вправе включить условие о внесудебном порядке обращения взыскания в договор залога.\n\n5. Соглашение об обращении взыскания во внесудебном порядке на заложенное имущество должно быть заключено в той же форме, что и договор залога этого имущества.\n\n6. Обращение взыскания на предмет залога по исполнительной надписи нотариуса без обращения в суд допускается в порядке, установленном законодательством о нотариате и законодательством Российской Федерации об исполнительном производстве, в случае неисполнения или ненадлежащего исполнения должником обеспеченного залогом обязательства, если договор залога, содержащий условие об обращении взыскания на заложенное имущество во внесудебном порядке, удостоверен нотариально.\n\n7. Соглашение об обращении взыскания на заложенное имущество во внесудебном порядке должно содержать указание на один способ или несколько способов реализации заложенного имущества, предусмотренных настоящим Кодексом, а также стоимость (начальную продажную цену) заложенного имущества или порядок ее определения.\n\nВ случае, если соглашение об обращении взыскания на заложенное имущество предусматривает несколько способов реализации заложенного имущества, право выбора способа реализации принадлежит залогодержателю при условии, что соглашением не предусмотрено иное.\n\n8. Если обращение взыскания на заложенное имущество осуществляется во внесудебном порядке, залогодержатель или нотариус, который производит обращение взыскания на заложенное имущество в порядке, установленном законодательством о нотариате, обязан направить залогодателю, известным им залогодержателям, а также должнику уведомление о начале обращения взыскания на предмет залога.\n\nРеализация заложенного имущества допускается не ранее чем через десять дней с момента получения залогодателем и должником уведомления залогодержателя или нотариуса, если иной срок не предусмотрен законом, а также если больший срок не предусмотрен соглашением между залогодержателем и залогодателем. В случаях, предусмотренных банковским законодательством, реализация заложенного движимого имущества может быть осуществлена до истечения указанного срока при существенном риске значительного снижения стоимости предмета залога по сравнению с ценой реализации (начальной продажной ценой), указанной в уведомлении.","article_title":"Статья 349. Порядок обращения взыскания на заложенное имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c253b65d7fef88684c7318998641319e975751c1cab3c2c3f0e5198fb35d81a6"},{"code_id":"GK_RF","article_number":"35","version_date":"1994-11-30","article_text":"1. Опекун или попечитель назначается органом опеки и попечительства по месту жительства лица, нуждающегося в опеке или попечительстве, в течение месяца с момента, когда указанным органам стало известно о необходимости установления опеки или попечительства над гражданином. При наличии заслуживающих внимания обстоятельств опекун или попечитель может быть назначен органом опеки и попечительства по месту жительства опекуна (попечителя). Если лицу, нуждающемуся в опеке или попечительстве, в течение месяца не назначен опекун или попечитель, исполнение обязанностей опекуна или попечителя временно возлагается на орган опеки и попечительства.\n\nНазначение опекуна или попечителя может быть оспорено в суде заинтересованными лицами. (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 35. Опекуны и попечители","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c867591a7c1d13ac8c2c851129e6f507fc159e084fb3f2f66ff840998b3fa778"},{"code_id":"GK_RF","article_number":"350","version_date":"1994-11-30","article_text":"1. Реализация заложенного имущества, на которое взыскание обращено на основании решения суда, осуществляется путем продажи с публичных торгов в порядке, установленном настоящим Кодексом и процессуальным законодательством, если законом или соглашением между залогодержателем и залогодателем не установлено, что реализация предмета залога осуществляется в порядке, установленном абзацами вторым и третьим пункта 2 статьи 3501 настоящего Кодекса.\n\n2. При обращении взыскания на заложенное имущество в судебном порядке суд по просьбе залогодателя, являющегося должником по обязательству, при наличии уважительных причин вправе отсрочить продажу заложенного имущества с публичных торгов на срок до одного года.\n\nОтсрочка не освобождает должника от возмещения возросших за время отсрочки убытков кредитора, процентов и неустойки.","article_title":"Статья 350. Реализация заложенного имущества при обращении на него взыскания в судебном порядке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16a49f0c336479325782b1f0dc7d762a64b876bd2187d82b8f6e5bbccfe3e309"}]$law7d0024$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
